import { BootDocument } from "@/features/boot/boot.graphql";
import { proxyGraphql } from "@/lib/backend";
import persistedDocuments from "@/lib/graphql/generated/persisted-documents.json";

/**
 * hash → document, generated by `pnpm codegen` from features/*\/*.graphql.ts,
 * minus Boot: it's the SSR prefetch's all-sections query, never sent by the
 * browser, and allowing it would let one request run every resolver.
 */
const DOCUMENTS: Readonly<Record<string, string>> = Object.fromEntries(
  Object.entries(persistedDocuments as Record<string, string>).filter(
    ([hash]) => hash !== BootDocument.__meta__?.hash,
  ),
);

function badRequest(message: string): Response {
  return Response.json({ message }, { status: 400 });
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * The browser's only way to GraphQL. It sends `{ id, variables }`, where
 * `id` is the hash of an operation this app ships; the query text is
 * looked up here. Raw queries and unknown hashes are rejected, so the
 * browser can't use this route to run arbitrary queries against
 * port-server — the same property the per-section REST routes had.
 */
export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return badRequest("BODY MUST BE JSON");
  }
  if (!isPlainObject(body) || typeof body.id !== "string") {
    return badRequest("EXPECTED { id, variables? }");
  }
  if (!Object.hasOwn(DOCUMENTS, body.id)) {
    return badRequest("UNKNOWN OPERATION");
  }
  if (body.variables !== undefined && !isPlainObject(body.variables)) {
    return badRequest("VARIABLES MUST BE AN OBJECT");
  }
  return proxyGraphql(request, DOCUMENTS[body.id], body.variables);
}
